import{_ as t,a as e,b as c}from"./chunks/non_deterministic_computation_2_gm_data_change_process.D0Jw-8Jh.js";import{_ as i,o as l,a as d,b as s}from"./app.C41L12d5.js";const o="/ascendc.github.io/assets/software_synchronization_between_two_cores_flowchart.XKKRnKwK.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"原子操作","link":"/api/SIMD-API/c_api/atomic/atomic"},{"text":"关键特性说明","link":"/api/SIMD-API/c_api/atomic/key_features"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/atomic/key_features.md","filePath":"api/SIMD-API/c_api/atomic/key_features.md","outlineHeaders":[{"level":2,"title":"确定性计算概述","slug":"确定性计算概述","link":"#确定性计算概述"},{"level":2,"title":"非确定性计算，结果1","slug":"非确定性计算，结果1","link":"#非确定性计算，结果1"},{"level":2,"title":"非确定性计算，结果2","slug":"非确定性计算，结果2","link":"#非确定性计算，结果2"},{"level":2,"title":"确定性计算实现方案","slug":"确定性计算实现方案","link":"#确定性计算实现方案"},{"level":2,"title":"核内同步","slug":"核内同步","link":"#核内同步"},{"level":2,"title":"核间同步","slug":"核间同步","link":"#核间同步"}],"lastUpdated":1787832553000}'),_={name:"api/SIMD-API/c_api/atomic/key_features.md"};function p(n,a,r,h,m,M){return l(),d("div",null,[...a[0]||(a[0]=[s(`<div><article class="markdown-body"><h1>关键特性说明</h1><p>确定性计算是指在相同输入条件下，无论执行次数或执行环境如何变化，总能产生完全一致输出结果的计算过程。确定性计算为系统稳定性和实验可验证性提供保障。</p><p>对下文描述中出现的接口有以下说明：</p><ul><li>对于浮点数类型的原子累加，本文以<code>asc_set_atomic_add_float()</code>为例，更多原子操作类型参考<a href="datamove_atomic/asc_set_atomic_add.html">asc_set_atomic_add</a>。</li><li>对于原子最大和原子最小，本文以<code>asc_set_atomic_max_float()</code>和<code>asc_set_atomic_min_float()</code>为例，更多原子操作类型参考<a href="datamove_atomic/asc_set_atomic_max.html">asc_set_atomic_max</a>和<a href="datamove_atomic/asc_set_atomic_min.html">asc_set_atomic_min</a>。</li><li>对于AIV和AIC中向GM搬运数据的接口，本文分别以<code>asc_copy_ub2gm()</code>和<code>asc_copy_l0c2gm()</code>为例，更多搬运接口参考<a href="../vector_datamove/vector_datamove.html">矢量数据搬运</a>和<a href="../cube_datamove/cube_datamove.html">矩阵计算搬运</a>。</li></ul><h2 id="确定性计算概述">确定性计算概述<a class="header-anchor" href="#确定性计算概述">​</a></h2><p>为引出原子操作场景下非确定性计算的问题，我们构建如下常见的确定性计算场景：首先，通过单组浮点数数据搬运完成GM的初始化；随后，启动原子累加操作；最后，经由多次数据搬运，在GM上对多组浮点数数据进行累加。具体伪代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>1. 向GM搬运数据data0;    // 数据搬运，覆盖GM原有随机值，期望GM数据为data0。
2. asc_set_atomic_add_float();         // 开启原子累加，后续从Unified Buffer（UB）/L0C Buffer/L1 Buffer到GM的搬运均执行原子累加。
3. 向GM搬运data1;    // 带随路原子操作的数据搬运，期望GM数据为data0 + data1。
4. 向GM搬运data2;    // 带随路原子操作的数据搬运，期望GM数据为data0 + data1 + data2。
5. 向GM搬运data3;    // 带随路原子操作的数据搬运，期望GM数据为data0 + data1 + data2 + data3。
</code></pre></div><p>如下图1所示，开发者的预期结果：指令发射的顺序能够严格对应实际指令执行顺序，多次执行该段代码，无论执行多少次，最终GM数据均为data0 + data1 + data2 + data3，结果完全一致，实现确定性计算。</p><p><strong>图1</strong> 确定性计算场景，GM上数据变化过程 <img src="`+t+'" alt title="Deterministic computation scenario, GM data change process"></p><p>但实际情况是，若开发者不做干预，程序每次运行时这些指令的执行顺序都可能发生变化，最终导致GM数据与预期结果不一致。下面列举两种可能的指令执行顺序及其对应的执行流程。</p><h2 id="非确定性计算，结果1">非确定性计算，结果1<a class="header-anchor" href="#非确定性计算，结果1">​</a></h2><p><strong>图2</strong> 非确定性计算场景1，GM上数据变化过程 <img src="'+e+'" alt title="Non-deterministic computation scenario 1, GM data change process"></p><p>如图2所示，该场景中指令执行流程如下：</p><ol><li>初始状态，GM数据为：随机值；</li><li>向GM搬运data0，GM数据被初始化为：data0；</li><li>执行<code>asc_set_atomic_add_float()</code>，为后续搬运指令开启原子累加，GM数据为：data0；</li><li>三次带随路原子操作的搬运指令乱序，实际执行顺序为“搬出data2→搬出data3→搬出data1”，最终GM上数据为：data0 + data2 + data3 + data1。</li></ol><p><strong>非确定性计算的产生原因1：</strong></p><p>带随路原子操作的搬运指令乱序，由于浮点数加法不满足结合律，即(a+b)+c!=a+(b+c)，使得最终GM数据data0 + data2 + data3 + data1与预期的data0 + data1 + data2 + data3存在偏差。</p><p>带随路原子操作的搬运指令乱序，导致最终结果产生偏差的前提条件有以下三条：</p><ul><li>原子操作类型为原子累加（最大值、最小值运算满足结合律）。</li><li>原子操作数据类型为浮点数（整数加法满足结合律）。</li><li>带随路原子操作的搬运指令达到3条及以上（浮点数加法满足交换律，但是不满足结合律）。</li></ul><h2 id="非确定性计算，结果2">非确定性计算，结果2<a class="header-anchor" href="#非确定性计算，结果2">​</a></h2><p><strong>图3</strong> 非确定性计算场景2，GM上数据变化过程 <img src="'+c+`" alt title="Non-deterministic computation scenario 2, GM data change process"></p><p>如图3所示，该场景中指令执行流程如下：</p><ol><li>初始状态，GM数据为：随机值；</li><li>执行<code>asc_set_atomic_add_float()</code>，为后续搬运指令开启原子累加，GM数据为：随机值；</li><li>先后执行两次带随路原子操作的搬运指令，执行顺序为“搬出data1→搬出data2”，GM数据为：随机值 + data1 + data2；</li><li>向GM搬运data0，GM上累加的结果被data0覆盖，GM数据为：data0；</li><li>最后执行data3的搬运，最终GM上数据为：data0 + data3。</li></ol><p><strong>非确定性计算的产生原因2：</strong></p><p>开启原子累加前的普通搬运指令与开启原子操作的搬运指令之间发生乱序，会导致GM上已完成原子操作的数据被data0错误覆盖，进而产生非确定性计算结果。</p><p>此类乱序导致结果偏差无需满足任何前提条件，开发者无需再区分原子操作类型、原子操作数据类型，也无需考虑带随路原子操作的搬运指令数量是否达到3条及以上。</p><h2 id="确定性计算实现方案">确定性计算实现方案<a class="header-anchor" href="#确定性计算实现方案">​</a></h2><p>根据导致非确定性计算的两个根因，下面也从解决这两个方面描述确定性计算实现的方案。核心思想是在指令之间插入适当的同步，使每次程序运行时相关指令都按照预期确定的顺序执行，最终保证每次执行程序输出的结果都相同。具体来说包含以下两个方面：</p><ul><li><p>开启原子累加前的搬运指令与开启原子操作的指令之间插入同步</p><p>如下伪代码所示，在指令1与2之间插入同步，能够确保开始原子操作前GM的初始值符合预期。</p></li><li><p>开启原子累加操作后，多条搬运指令之间的同步</p><p>指令3与4、4与5之间插入同步，能够确保浮点数累加的顺序符合预期。</p><div class="callout callout-caution"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M4.47.22A.749.749 0 0 1 5 0h6c.199 0 .389.079.53.22l4.25 4.25c.141.14.22.331.22.53v6a.749.749 0 0 1-.22.53l-4.25 4.25A.749.749 0 0 1 11 16H5a.749.749 0 0 1-.53-.22L.22 11.53A.749.749 0 0 1 0 11V5c0-.199.079-.389.22-.53Zm.84 1.28L1.5 5.31v5.38l3.81 3.81h5.38l3.81-3.81V5.31L10.69 1.5ZM8 4a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 8 4Zm0 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意</p><p>开启原子操作的指令与后续搬运指令之间的同步由硬件保证。</p></div></li></ul><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 整个原子累加在同一个核内执行，控制5个指令的执行顺序为“1→2→3→4→5”。
1. 向GM搬运数据data0;    // 数据搬运，覆盖GM原有随机值，期望GM数据为data0。
核内同步
2. asc_set_atomic_add_float();         // 开启原子累加，后续从UB/L0C Buffer/L1 Buffer到GM的搬运均执行原子累加。
// 指令2与3间无需插入同步。
3. 向GM搬运data1;    // 开启原子累加后的数据搬运，期望GM数据为data0 + data1。
核内同步
4. 向GM搬运data2;    // 开启原子累加后的数据搬运，期望GM数据为data0 + data1 + data2。
核内同步
5. 向GM搬运data3;    // 开启原子累加后的数据搬运，期望GM数据为data0 + data1 + data2 + data3。
</code></pre></div><p>如下伪代码所示，在一个纯Vector算子中，当上述指令都在不同AIV核中执行时，需要将上述的核内同步替换为核间同步。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 整个原子累加在4个不同核中执行，控制4个核执行的顺序为“核0→核1→核2→核3”。
if (block_idx == 0) {
   向GM搬运数据data0;
   核间同步
} else if (block_idx == 1) {
   核间同步
   asc_set_atomic_add_float();
   向GM搬运data1;
   核间同步
} else if (block_idx == 2) {
   核间同步
   asc_set_atomic_add_float();
   向GM搬运data2;
   核间同步
} else if (block_idx == 3) {
   核间同步
   asc_set_atomic_add_float();
   向GM搬运data3;
}
</code></pre></div><p>下面介绍如何基于硬件同步指令实现核内同步，以及如何基于软件同步方案实现核间同步。</p><h2 id="核内同步">核内同步<a class="header-anchor" href="#核内同步">​</a></h2><p>搬运指令和开启原子操作的指令流水类型如下表所示，当上述指令在同一个核内执行时，开发者按需插入<a href="../sync/asc_sync_pipe.html">asc_sync_pipe</a>或者<a href="../sync/asc_sync_notify.html">asc_sync_notify</a>与<a href="../sync/asc_sync_wait.html">asc_sync_wait</a>。</p><p><strong>表1</strong> 原子操作确定性计算相关指令的流水类型</p><table><thead><tr><th>指令名称</th><th>流水类型</th></tr></thead><tbody><tr><td>asc_copy_ub2gm</td><td>PIPE_MTE3</td></tr><tr><td>asc_copy_l0c2gm</td><td>PIPE_FIX</td></tr><tr><td>asc_set_atomic_add_float()/asc_set_atomic_max_float()/asc_set_atomic_min_float()</td><td>PIPE_S</td></tr></tbody></table><h2 id="核间同步">核间同步<a class="header-anchor" href="#核间同步">​</a></h2><p>由于当前未提供用于控制不同核之间执行顺序的硬件同步接口，因此确定性计算场景下的核间同步需通过软件仿真实现：通过GM中的信号量实现核间同步，先建立一对核（AIV或AIC）之间的同步，进而扩展至多个核之间的同步。</p><p>下图展示了两个核之间如何通过GM中的信号量进行核间同步：</p><ul><li><p>上一个核完成数据搬运或开启原子操作后，会通过Scalar单元向核间共享的GM中的信号量写入值1，表示自己的任务已完成。上一个核中也需要插入核内同步：</p><ul><li>当上一个核内有多条搬运指令时，它们之间需要插入核内同步1。</li><li>Scalar单元向GM写数据之前必须保证前序所有搬运指令都已经执行完成，因此它们之间也需要插入核内同步2。</li></ul></li><li><p>当前核在执行搬运任务前，会通过Scalar单元不断读取该信号量的值。如果信号量不等于1，当前核会进入阻塞等待状态；当检测到信号量等于1时，当前核会解除阻塞，开始执行自己的数据搬运或原子操作。为确保信号量等于1之前，当前核不会执行搬运指令，需要在搬运指令之前插入核内同步3。</p></li></ul><p><strong>图4</strong> 一对核之间软件同步方案流程图<br><img src="`+o+'" alt title="Software synchronization flowchart between two cores"></p><p>Scalar单元访问GM上的信号量，存在两种访问方式：</p><ul><li><p>经过DCache访问</p><p>当开发者通过<code>x_gm[i]</code>（其中<code>x_gm</code>为<code>__gm__</code>类型指针）读写GM时，需手动调用<a href="../cache_ctrl/asc_dcci.html">asc_dcci</a>接口，以保证多核间的数据一致性。</p></li><li><p>不通过DCache访问</p><p>使用<a href="../scalar_compute/scalar_store/asc_store_dev.html">asc_store_dev</a>和与其对应的绕过DCache读取能力直接访问GM。这种方式无需额外操作即可保证多核间数据的一致性。</p></li></ul><p>如图4所示，核间同步方案中也需要与核内同步配合使用，现将三处核内同步作用说明如下：</p><ul><li>核内同步1（可选）：核内存在多条数据搬运指令时，通过该同步保证各搬运操作严格按顺序执行。</li><li>核内同步2（必备）：等待前一个核全部任务执行完毕后，才允许Scalar单元向全局内存信号量写入1。</li><li>核内同步3（必备）：等待Scalar单元检测到信号量更新为1后，当前核再启动后续任务执行。</li></ul></article></div>',1)])])}const u=i(_,[["render",p]]);export{g as __pageData,u as default};
